use zwen_core::{journal::{Journal,TurnState},completion::{Message,Role}};
fn path()->std::path::PathBuf{let p=std::env::temp_dir().join(format!("zwen-context-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&p).unwrap();p.join("chat.sqlite3")}
#[test] fn continuation_preserves_order_and_provider_binding(){let p=path();let mut s=Journal::open(&p).unwrap();let mut t=s.begin_in("one","first","m",None,"provider-a",0).unwrap();t.answer="answer".into();t.state=TurnState::Complete;t.revision=1;s.checkpoint(&t).unwrap();let context=s.context(Some("one"),"provider-a",5).unwrap();assert_eq!(context,vec![Message{role:Role::User,content:"first".into()},Message{role:Role::Assistant,content:"answer".into()}]);assert!(s.context(Some("one"),"provider-b",5).is_err());assert!(s.context(Some("missing"),"provider-a",5).is_err());let next=s.begin_in("two","second","m",Some("one"),"provider-a",1).unwrap();assert_eq!(next.conversation_id,"one");assert_eq!(s.history(0,20).unwrap().len(),2);assert_eq!(s.find("one").unwrap().unwrap().answer,"answer");drop(s);std::fs::remove_dir_all(p.parent().unwrap()).unwrap();}
#[test] fn context_is_bounded_and_never_silently_omits_the_latest_large_pair(){let p=path();let mut s=Journal::open(&p).unwrap();for i in 0..10{let id=format!("r{i}");let mut t=s.begin_in(&id,"q","m",if i==0{None}else{Some("r0")},"profile",0).unwrap();t.answer="a".into();t.revision=1;t.state=TurnState::Complete;s.checkpoint(&t).unwrap();}assert_eq!(s.context(Some("r0"),"profile",1).unwrap().len(),16);assert!(s.context(Some("r0"),"profile",256*1024-1).is_err());drop(s);std::fs::remove_dir_all(p.parent().unwrap()).unwrap();}
